\label{altdef} (see \cite[Proposition 2.1]{NaRy})
Let $u:[0,l)\to\mathbb{R}$ be such that $u\in C^2(0,l)\cap C[0,l)$ and $u'\in L^1(0,l)$.
Then, $(D^\alpha_x u)_x$ exists everywhere in $(0,l)$ and
\begin{equation}\label{e:another}
\begin{split}
(D^\alpha u)_x(x)=
\frac{1}{\Gamma(1-\alpha)}&\left(\frac{\alpha(u(0)-u(x))+(\alpha+1)u'(x)x}{x^{\alpha+1}}\right.\\
&\quad\left.+\alpha(\alpha+1)\int_0^x[u(x-z)-u(x)+u'(x)z]\frac{dz}{z^{\alpha+2}}\right)
\end{split}
\end{equation}
for $x\in(0,l)$.

\label{rnieE} (see \cite[Example 4.11]{kilbas},  \cite[Theorem 4]{saigo})
Function $\Phi$ defined in (\ref{def-phi}) satisfies the following fractional ordinary differential equation,
\begin{equation}\label{ode}
 D_{y_C}^\alpha v(y)+\frac{1}{1+\alpha}yv(y)=0, \quad y>0, \qquad v(0) = 1. 
\end{equation}

\label{thm-main}
Function ${\mathscr{E}}: (0,\infty)^2 \to \mathbb{R}$ given by formula  
\begin{equation}\label{defE}
    {\mathscr{E}}(x,t) = a_0 t^{-\frac{1}{1+\alpha}} 
    E_{\alpha, 1+1/\alpha, 1/\alpha}\left( -\frac{x^{1+\alpha}}{ (1+\alpha)t}\right).
\end{equation}
where                                                          
\begin{equation}\label{df-a0}
\frac{1}{a_0} = 2\int_0^\infty E_{\alpha, 1+1/\alpha, 1/\alpha}( -x^{1+\alpha}/ (1+\alpha))\,dx
\end{equation}
is well-defined:\\                            
(1) ${\mathscr{E}}\in C^2((0,\infty)^2)$ and ${\mathscr{E}}$   is a self-similar solution to (\ref{rn1}), i.e. it is invariant under the transformation $(x,t) \mapsto (\lambda^{\frac1{1+\alpha}} x, \lambda t)$ for $\lambda>0$.\\
(2)  ${\mathscr{E}}$ is positive for all $x,t >0$.\\
(3) For all  $t>0$ function ${\mathscr{E}}(\cdot,t)$ is decreasing.\\
(4) For all  $t>0$ function ${\mathscr{E}}(\cdot,t)$ is in $L^1(0, \infty)$ and
the integral $\int_0^\infty {\mathscr{E}}(x,t)\,dx=\frac 12$.

\label{le-posit}
Function 

$\Phi$  defined in (\ref{def-phi}) is positive for all $x>0$.

\label{le-pom}
If $U\in C^{1+\alpha}([0,\infty))$ and $u(x,t) = U(x t^{-\frac1{1+\alpha}})$ satisfies inequality 
\begin{equation}\label{2nier}
 \left(\frac\partial{\partial t} - \frac{\partial }{\partial x}D^\alpha_{x_C} \right) u>0
\end{equation}
in $\Omega$ defined in (\ref{def-om}), where $x_1>0$ is now arbitrary, then $u(x,1) \equiv U(x)$ cannot attain a minimum inside $(0, x_1)$. \qed

\label{le-int}
Function $\Phi$  defined in (\ref{def-phi})

is bounded with a bound uniform in $\alpha$ and it is integrable over $(0,\infty).$

\label{prop1}
Let us suppose that  $g\in L^p(0,\infty),$ where  $p\in[1,\infty)$ and $g$ has compact support, (resp. $g\in C^0_c([0,\infty))$

and   we set 
$$
{\mathscr{E}}_t(x) = {\mathscr{E}}(x,t).
$$
We define functions $w_1$, $w_2$ by the following formulas,
\begin{equation}\label{rn3.5}
w_1(x,t) = \int_0^\infty ( {\mathscr{E}}(x-y,t) - {\mathscr{E}}(x+y, t))g(y)\,dy,
\end{equation}
\begin{equation}\label{rn3.6}
w_2(x,t)  = \int_0^\infty ( {\mathscr{E}}(x-y,t) + {\mathscr{E}}(x+y, t))g(y)\,dy.
\end{equation}
Then, \\
(a) For all $t, R>0$ functions $w_1(\cdot,t)$ and $w_2(\cdot,t)$ belong to $C^{1+\alpha}([0,R])$, they are classical solutions to 
\begin{equation}\label{rn3}
\begin{array}{ll}\displaystyle{
\frac{\partial w }{\partial t} - \frac{\partial  }{\partial x} D^\alpha w = 0}      & x,t >0, \\
 ~ & ~\\
w(x,0) = g(x)     & x>0.
\end{array}
\end{equation}
In addition $w_1$ (resp. $w_2$) satisfies the Dirichlet (resp. Neumann) boundary condition,
\begin{equation}\label{r12.5}
    w(0,t) = 0,\qquad (\hbox{resp. } w_x(0,t)=0)\qquad \hbox{for }t>0.
\end{equation}
(b) Functions $w_1$ and $w_2$ belong to $L^\infty(\mathbb{R}_+; L^p(\mathbb{R}_+))$ if $p<\infty$ (resp. $w_1, w_2 \in L^\infty(\mathbb{R}_+; C(\mathbb{R}_+))$, when $g\in C^0_c([0,\infty))$).
The initial condition is satisfied in the sense below. However, when $g$ is continuous, we require $g(0) =0$ in case of the Dirichlet data,
\begin{equation}\label{r-ic}
 \lim_{t\to 0}\|w_1(\cdot, t) - g\|_{L^p} =0, \qquad(\hbox{resp. }
\lim_{t\to 0}\|w_2(\cdot, t) - g\|_{L^\infty} =0).   
\end{equation}

\label{le-zanik}
Let us suppose that $\Phi$ is given by (\ref{def-phi}). Then, 

for all $x>0$ we have,
$$
0< x \,\Phi (x)\le 2.
$$

We consider eq. (*)              
for $v$ with the initial condition $v(0) = 1$








Then, $v(x) \equiv E_{\alpha, 1+\frac{1}{\alpha}, \frac{1}{\alpha}}(-\frac{x^{1+\alpha}}{1+\alpha})$ is a solution to (*). 

Let us suppose our claim is not valid and the set
\begin{equation*}
A := \{ x>0 : v(x) \leq 0 \}
\end{equation*}
is not empty. Due to the continuity of $v$, there is $x_0$ such that
\begin{equation*}
v(x_0) = 0\qquad\hbox{and}\qquad



v(x) >0 \quad \mbox{for} \,\, x \in (0, x_0).


\end{equation*}
However, we have
\begin{align*}
\displaystyle v(x_0) &= -\frac{1+\alpha}{x_0}D_{x}^{\alpha}v(x_0) \\
 &= -\frac{1+\alpha}{x_0 \Gamma(1-\alpha)} \left( \frac{v(x_0) - v(0)}{x_0^\alpha} + \alpha \int_0^{x_0} \frac{v(x_0) - v(x_0 - z)}{z^{\alpha + 1}} dz \right) \\
 &= \frac{1+\alpha}{x_0 \Gamma(1-\alpha)} \left( \frac{1}{x_0^\alpha} + \alpha \int_0^{x_0} \frac{v(x_0 - z)}{z^{\alpha + 1}} dz \right) > 0.
\end{align*}
This is a contradiction.
